    'index.html',
    'page_a.html',
    'page_b.html',
    'level2_1.html',
    'level2_2.html',
    'level2_3.html',
]
EXPECTED_LEVEL3 = ['level3_x.html', 'level3_y.html', 'level3_z.html']
EXPECTED_BFS_LEVELS_3 = EXPECTED_BFS_LEVELS_2 + EXPECTED_LEVEL3

